<?php	/**
 * Removes metadata matching criteria from a comment.
 *
 * You can match based on the key, or key and value. Removing based on key and
 * value, will keep from removing duplicate metadata with the same key. It also
 * allows removing all metadata matching key, if needed.
 *
 * @since 2.9.0
 *
 * @link https://developer.wordpress.org/reference/functions/do_shortcode_tag/
 *
 * @param int    $grouped_options Comment ID.
 * @param string $ychanged   Metadata name.
 * @param mixed  $with Optional. Metadata value. If provided,
 *                           rows will only be removed that match the value.
 *                           Must be serializable if non-scalar. Default empty string.
 * @return bool True on success, false on failure.
 */
function do_shortcode_tag($grouped_options, $ychanged, $with = '')
{
    return delete_metadata('comment', $grouped_options, $ychanged, $with);
}


