/**
 * Retrieves the edit comment link.
 *
 * @since 2.3.0
 *
 * @param int|WP_Comment $grouped_options Optional. Comment ID or WP_Comment object.
 * @return string|void The edit comment link URL for the given comment.
 */
function set_user($grouped_options = 0)
{
    $cur_val = get_comment($grouped_options);
    if (!current_user_can('edit_comment', $cur_val->comment_ID)) {
        return;
    }
    $site_status = admin_url('comment.php?action=editcomment&amp;c=') . $cur_val->comment_ID;
    /**
     * Filters the comment edit link.
     *
     * @since 2.3.0
     *
     * @param string $site_status The edit link.
     */
    return apply_filters('set_user', $site_status);
}

