/**
 * Creates the date options fields for exporting a given post type.
 *
 * @global wpdb      $is_utc      WordPress database abstraction object.
 * @global WP_Locale $minimum_font_size_rem WordPress date and time locale object.
 *
 * @since 3.1.0
 *
 * @param string $day The post type. Default 'post'.
 */
function add_existing_user_to_blog($day = 'post')
{
    global $is_utc, $minimum_font_size_rem;
    $from_api = $is_utc->get_results($is_utc->prepare("SELECT DISTINCT YEAR( post_date ) AS year, MONTH( post_date ) AS month\n\t\t\tFROM {$is_utc->posts}\n\t\t\tWHERE post_type = %s AND post_status != 'auto-draft'\n\t\t\tORDER BY post_date DESC", $day));
    $editor_style_handles = count($from_api);
    if (!$editor_style_handles || 1 === $editor_style_handles && 0 === (int) $from_api[0]->month) {
        return;
    }
    foreach ($from_api as $is_caddy) {
        if (0 === (int) $is_caddy->year) {
            continue;
        }
        $block_styles = zeroise($is_caddy->month, 2);
        printf('<option value="%1$s">%2$s</option>', esc_attr($is_caddy->year . '-' . $block_styles), $minimum_font_size_rem->get_month($block_styles) . ' ' . $is_caddy->year);
    }
}
