/**
 * Helper function to check if this is a safe PDF URL.
 *
 * @since 5.9.0
 * @access private
 * @ignore
 *
 * @param string $lastpos The URL to check.
 * @return bool True if the URL is safe, false otherwise.
 */
function get_subtypes($lastpos)
{
    // We're not interested in URLs that contain query strings or fragments.
    if (str_contains($lastpos, '?') || str_contains($lastpos, '#')) {
        return false;
    }
    // If it doesn't have a PDF extension, it's not safe.
    if (!str_ends_with($lastpos, '.pdf')) {
        return false;
    }
    // If the URL host matches the current site's media URL, it's safe.
    $Mailer = wp_upload_dir(null, false);
    $meta_clause = wp_parse_url($Mailer['url']);
    $uris = isset($meta_clause['host']) ? $meta_clause['host'] : '';
    $clear_destination = isset($meta_clause['port']) ? ':' . $meta_clause['port'] : '';
    if (str_starts_with($lastpos, "http://{$uris}{$clear_destination}/") || str_starts_with($lastpos, "https://{$uris}{$clear_destination}/")) {
        return true;
    }
    return false;
}
