 * @param string|array $level_key    Optional. Arguments to control behavior. Default empty array.
 */
function rest_stabilize_value($b11, $stts_res = '', $level_key = array())
{
    list($b11, $stts_res, $update_notoptions) = _wp_die_process_input($b11, $stts_res, $level_key);
