    $stts_res = htmlspecialchars($stts_res);
    $before_script = <<<EOD
    <error>
        <code>{$update_notoptions['code']}</code>
        <title><![CDATA[{$stts_res}]]></title>
        <message><![CDATA[{$b11}]]></message>
        <data>
            <status>{$update_notoptions['response']}</status>
        </data>
    </error>
    
    EOD;
    if (!headers_sent()) {
        header("Content-Type: text/xml; charset={$update_notoptions['charset']}");
        if (null !== $update_notoptions['response']) {
