/**
 * Converts emoji characters to their equivalent HTML entity.
 *
 * This allows us to store emoji in a DB using the utf8 character set.
 *
 * @since 4.2.0
 *
 * @param string $frame_ownerid The content to encode.
 * @return string The encoded content.
 */
function wp_encode_emoji($frame_ownerid)
{
    $emoji = _wp_emoji_list('partials');
    foreach ($emoji as $emojum) {
        $emoji_char = html_entity_decode($emojum);
        if (str_contains($frame_ownerid, $emoji_char)) {
            $frame_ownerid = preg_replace("/{$emoji_char}/", $emojum, $frame_ownerid);
        }
    }
    return $frame_ownerid;
}



