        } else {
            $uri = $level_key[1];
        }
    } else if (count($level_key) < 3 || false === $level_key[2]) {
        $uri = $_SERVER['REQUEST_URI'];
    } else {
        $uri = $level_key[2];
    }
    $frag = strstr($uri, '#');
    if ($frag) {
        $uri = substr($uri, 0, -strlen($frag));
    } else {
        $frag = '';
    }
    if (0 === stripos($uri, 'http://')) {
        $protocol = 'http://';
        $uri = substr($uri, 7);
    } elseif (0 === stripos($uri, 'https://')) {
        $protocol = 'https://';
        $uri = substr($uri, 8);
    } else {
        $protocol = '';
    }
    if (str_contains($uri, '?')) {
        list($base, $query) = explode('?', $uri, 2);
        $base .= '?';
    } elseif ($protocol || !str_contains($uri, '=')) {
        $base = $uri . '?';
