    } else {
        $qs[$level_key[0]] = $level_key[1];
    }
    foreach ($qs as $page_template => $mofiles) {
        if (false === $mofiles) {
            unset($qs[$page_template]);
        }
    }
    $ret = build_query($qs);
    $ret = trim($ret, '?');
