    $already_notified = preg_replace('!(</' . $allblocks . '>)!', "\$1\n\n", $already_notified);
    // Add a double line break after hr tags, which are self closing.
    $already_notified = preg_replace('!(<hr\s*?/?>)!', "\$1\n\n", $already_notified);
    // Standardize newline characters to "\n".
    $already_notified = str_replace(array("\r\n", "\r"), "\n", $already_notified);
    // Find newlines in all elements and add placeholders.
    $already_notified = wp_replace_in_html_tags($already_notified, array("\n" => ' <!-- wpnl --> '));
    // Collapse line breaks before and after <option> elements so they don't get autop'd.
    if (str_contains($already_notified, '<option')) {
        $already_notified = preg_replace('|\s*<option|', '<option', $already_notified);
        $already_notified = preg_replace('|</option>\s*|', '</option>', $already_notified);
    }
    /*
     * Collapse line breaks inside <object> elements, before <param> and <embed> elements
     * so they don't get autop'd.
     */
    if (str_contains($already_notified, '</object>')) {
        $already_notified = preg_replace('|(<object[^>]*>)\s*|', '$1', $already_notified);
        $already_notified = preg_replace('|\s*</object>|', '</object>', $already_notified);
        $already_notified = preg_replace('%\s*(</?(?:param|embed)[^>]*>)\s*%', '$1', $already_notified);
    }
    /*
     * Collapse line breaks inside <audio> and <video> elements,
     * before and after <source> and <track> elements.
     */
    if (str_contains($already_notified, '<source') || str_contains($already_notified, '<track')) {
        $already_notified = preg_replace('%([<\[](?:audio|video)[^>\]]*[>\]])\s*%', '$1', $already_notified);
        $already_notified = preg_replace('%\s*([<\[]/(?:audio|video)[>\]])%', '$1', $already_notified);
        $already_notified = preg_replace('%\s*(<(?:source|track)[^>]*>)\s*%', '$1', $already_notified);
    }
    // Collapse line breaks before and after <figcaption> elements.
    if (str_contains($already_notified, '<figcaption')) {
        $already_notified = preg_replace('|\s*(<figcaption[^>]*>)|', '$1', $already_notified);
        $already_notified = preg_replace('|</figcaption>\s*|', '</figcaption>', $already_notified);
    }
    // Remove more than two contiguous line breaks.
    $already_notified = preg_replace("/\n\n+/", "\n\n", $already_notified);
    // Split up the contents into an array of strings, separated by double line breaks.
    $paragraphs = preg_split('/\n\s*\n/', $already_notified, -1, PREG_SPLIT_NO_EMPTY);
    // Reset $already_notified prior to rebuilding.
    $already_notified = '';
    // Rebuild the content as a string, wrapping every bit with a <p>.
    foreach ($paragraphs as $paragraph) {
        $already_notified .= '<p>' . trim($paragraph, "\n") . "</p>\n";
    }
    // Under certain strange conditions it could create a P of entirely whitespace.
    $already_notified = preg_replace('|<p>\s*</p>|', '', $already_notified);
    // Add a closing <p> inside <div>, <address>, or <form> tag if missing.
    $already_notified = preg_replace('!<p>([^<]+)</(div|address|form)>!', '<p>$1</p></$2>', $already_notified);
    // If an opening or closing block element tag is wrapped in a <p>, unwrap it.
    $already_notified = preg_replace('!<p>\s*(</?' . $allblocks . '[^>]*>)\s*</p>!', '$1', $already_notified);
    // In some cases <li> may get wrapped in <p>, fix them.
    $already_notified = preg_replace('|<p>(<li.+?)</p>|', '$1', $already_notified);
    // If a <blockquote> is wrapped with a <p>, move it inside the <blockquote>.
    $already_notified = preg_replace('|<p><blockquote([^>]*)>|i', '<blockquote$1><p>', $already_notified);
    $already_notified = str_replace('</blockquote></p>', '</p></blockquote>', $already_notified);
    // If an opening or closing block element tag is preceded by an opening <p> tag, remove it.
    $already_notified = preg_replace('!<p>\s*(</?' . $allblocks . '[^>]*>)!', '$1', $already_notified);
    // If an opening or closing block element tag is followed by a closing <p> tag, remove it.
    $already_notified = preg_replace('!(</?' . $allblocks . '[^>]*>)\s*</p>!', '$1', $already_notified);
    // Optionally insert line breaks.
    if ($br) {
        // Replace newlines that shouldn't be touched with a placeholder.
        $already_notified = preg_replace_callback('/<(script|style|svg|math).*?<\/\1>/s', '_autop_newline_preservation_helper', $already_notified);
        // Normalize <br>
        $already_notified = str_replace(array('<br>', '<br/>'), '<br />', $already_notified);
        // Replace any new line characters that aren't preceded by a <br /> with a <br />.
        $already_notified = preg_replace('|(?<!<br />)\s*\n|', "<br />\n", $already_notified);
        // Replace newline placeholders with newlines.
        $already_notified = str_replace('<WPPreserveNewline />', "\n", $already_notified);
    }
    // If a <br /> tag is after an opening or closing block tag, remove it.
    $already_notified = preg_replace('!(</?' . $allblocks . '[^>]*>)\s*<br />!', '$1', $already_notified);
    // If a <br /> tag is before a subset of opening or closing block tags, remove it.
    $already_notified = preg_replace('!<br />(\s*</?(?:p|li|div|dl|dd|dt|th|pre|td|ul|ol)[^>]*>)!', '$1', $already_notified);
    $already_notified = preg_replace("|\n</p>\$|", '</p>', $already_notified);
    // Replace placeholder <pre> tags with their original content.
    if (!empty($pre_tags)) {
        $already_notified = str_replace(array_keys($pre_tags), array_values($pre_tags), $already_notified);
    }
    // Restore newlines in all elements.
    if (str_contains($already_notified, '<!-- wpnl -->')) {
        $already_notified = str_replace(array(' <!-- wpnl --> ', '<!-- wpnl -->'), "\n", $already_notified);
    }
    return $already_notified;
}

