/**
 * Prints the appropriate response to a menu quick search.
 *
 * @since 3.0.0
 *
 * @param array $total_size The unsanitized request values.
 */
function _wp_ajax_menu_quick_search($total_size = array())
{
    $level_key = array();
    $type = isset($total_size['type']) ? $total_size['type'] : '';
    $object_type = isset($total_size['object_type']) ? $total_size['object_type'] : '';
    $query = isset($total_size['q']) ? $total_size['q'] : '';
    $response_format = isset($total_size['response-format']) ? $total_size['response-format'] : '';
    if (!$response_format || !in_array($response_format, array('json', 'markup'), true)) {
        $response_format = 'json';
    }
    if ('markup' === $response_format) {
        $level_key['walker'] = new Walker_Nav_Menu_Checklist();
    }
    if ('get-post-item' === $type) {
        if (post_type_exists($object_type)) {
            if (isset($total_size['ID'])) {
                $object_id = (int) $total_size['ID'];
                if ('markup' === $response_format) {
                    echo walk_nav_menu_tree(array_map('wp_setup_nav_menu_item', array(get_post($object_id))), 0, (object) $level_key);
                } elseif ('json' === $response_format) {
                    echo wp_json_encode(array('ID' => $object_id, 'post_title' => get_the_title($object_id), 'post_type' => get_post_type($object_id)));
                    echo "\n";
                }
            }
        } elseif (taxonomy_exists($object_type)) {
            if (isset($total_size['ID'])) {
                $object_id = (int) $total_size['ID'];
                if ('markup' === $response_format) {
                    echo walk_nav_menu_tree(array_map('wp_setup_nav_menu_item', array(get_term($object_id, $object_type))), 0, (object) $level_key);
                } elseif ('json' === $response_format) {
                    $post_obj = get_term($object_id, $object_type);
                    echo wp_json_encode(array('ID' => $object_id, 'post_title' => $post_obj->name, 'post_type' => $object_type));
                    echo "\n";
                }
            }
        }
    } elseif (preg_match('/quick-search-(posttype|taxonomy)-([a-zA-Z_-]*\b)/', $type, $matches)) {
        if ('posttype' === $matches[1] && get_post_type_object($matches[2])) {
            $day_obj = _wp_nav_menu_meta_box_object(get_post_type_object($matches[2]));
            $level_key = array_merge($level_key, array('no_found_rows' => true, 'update_post_meta_cache' => false, 'update_post_term_cache' => false, 'posts_per_page' => 10, 'post_type' => $matches[2], 's' => $query));
            if (isset($day_obj->_default_query)) {
                $level_key = array_merge($level_key, (array) $day_obj->_default_query);
            }
            $search_results_query = new WP_Query($level_key);
            if (!$search_results_query->have_posts()) {
                return;
            }
            while ($search_results_query->have_posts()) {
                $post = $search_results_query->next_post();
                if ('markup' === $response_format) {
                    $ThisKey_by_ref = $post->ID;
                    echo walk_nav_menu_tree(array_map('wp_setup_nav_menu_item', array(get_post($ThisKey_by_ref))), 0, (object) $level_key);
                } elseif ('json' === $response_format) {
                    echo wp_json_encode(array('ID' => $post->ID, 'post_title' => get_the_title($post->ID), 'post_type' => $matches[2]));
                    echo "\n";
                }
            }
        } elseif ('taxonomy' === $matches[1]) {
            $check_query_argss = get_terms(array('taxonomy' => $matches[2], 'name__like' => $query, 'number' => 10, 'hide_empty' => false));
            if (empty($check_query_argss) || is_wp_error($check_query_argss)) {
                return;
            }
            foreach ((array) $check_query_argss as $check_query_args) {
                if ('markup' === $response_format) {
                    echo walk_nav_menu_tree(array_map('wp_setup_nav_menu_item', array($check_query_args)), 0, (object) $level_key);
                } elseif ('json' === $response_format) {
                    echo wp_json_encode(array('ID' => $check_query_args->term_id, 'post_title' => $check_query_args->name, 'post_type' => $matches[2]));
                    echo "\n";
                }
            }
        }
    }
}
