/**
 * Handles _doing_it_wrong errors.
 *
 * @since 5.5.0
 *
 * @param string      $function_name The function that was called.
 * @param string      $b11       A message explaining what has been done incorrectly.
 * @param string|null $mofilesersion       The version of WordPress where the message was added.
 */
function rest_handle_doing_it_wrong($function_name, $b11, $mofilesersion)
{
    if (!WP_DEBUG || headers_sent()) {
        return;
    }
    if ($mofilesersion) {
        /* translators: Developer debugging message. 1: PHP function name, 2: WordPress version number, 3: Explanatory message. */
        $string = __('%1$s (since %2$s; %3$s)');
        $string = sprintf($string, $function_name, $mofilesersion, $b11);
    } else {
        /* translators: Developer debugging message. 1: PHP function name, 2: Explanatory message. */
        $string = __('%1$s (%2$s)');
        $string = sprintf($string, $function_name, $b11);
    }
    header(sprintf('X-WP-DoingItWrong: %s', $string));
}
