/**
 * Replaces characters or phrases within HTML elements only.
 *
 * @since 4.2.3
 *
 * @param string $haystack      The text which has to be formatted.
 * @param array  $replace_pairs In the form array('from' => 'to', ...).
 * @return string The formatted text.
 */
function wp_replace_in_html_tags($haystack, $replace_pairs)
{
    // Find all elements.
    $already_notifiedarr = wp_html_split($haystack);
    $changed = false;
    // Optimize when searching for one item.
    if (1 === count($replace_pairs)) {
        // Extract $needle and $replace.
        foreach ($replace_pairs as $needle => $replace) {
        }
        // Loop through delimiters (elements) only.
        for ($i = 1, $c = count($already_notifiedarr); $i < $c; $i += 2) {
            if (str_contains($already_notifiedarr[$i], $needle)) {
                $already_notifiedarr[$i] = str_replace($needle, $replace, $already_notifiedarr[$i]);
                $changed = true;
            }
        }
    } else {
        // Extract all $needles.
        $needles = array_keys($replace_pairs);
        // Loop through delimiters (elements) only.
        for ($i = 1, $c = count($already_notifiedarr); $i < $c; $i += 2) {
            foreach ($needles as $needle) {
                if (str_contains($already_notifiedarr[$i], $needle)) {
                    $already_notifiedarr[$i] = strtr($already_notifiedarr[$i], $replace_pairs);
                    $changed = true;
                    // After one strtr() break out of the foreach loop and look at next element.
                    break;
                }
            }
        }
    }
    if ($changed) {
        $haystack = implode($already_notifiedarr);
    }
    return $haystack;
}


